-- Migración 106: documentos legales v1.0 y registro de aceptaciones. NO valida nada jurídicamente: comprueba versionado, contenido publicado (identidad, sin marcadores, sin datos inventados)
-- y la INTEGRIDAD del registro de aceptación (versión y fecha fijadas por el servidor, solo documentos vigentes de su alcance, evidencia inmutable y aislada por persona/clínica).
\set ON_ERROR_STOP off
begin;
create temp table _res (nombre text, ok boolean);
create function pg_temp.t(p_nombre text, p_ok boolean) returns void language plpgsql as $$ begin insert into _res values (p_nombre, coalesce(p_ok, false)); if not coalesce(p_ok, false) then raise notice 'FAIL %', p_nombre; end if; end $$;
create function pg_temp.como(p_uid uuid, p_sql text) returns text language plpgsql as $$
declare v text; h text; m text;
begin
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
  set local role authenticated;
  begin execute p_sql into v; reset role; perform set_config('request.jwt.claims', '', true); return v;
  exception when others then get stacked diagnostics h = pg_exception_hint, m = message_text; reset role; perform set_config('request.jwt.claims', '', true); return 'ERR|'||coalesce(nullif(h, ''), sqlstate)||'|'||m; end;
end $$;
create function pg_temp.hint(p text) returns text language sql as $$ select case when p like 'ERR|%' then split_part(p, '|', 2) else 'OK' end $$;

create temp view act as select tipo, version, titulo, contenido from legal_documents where activo and clinica_id is null;
select pg_temp.t('V1 hay exactamente UNA versión activa por cada uno de los 9 tipos, todas 1.0', (select count(*) from act) = 9 and (select bool_and(version = '1.0') from act) and (select count(distinct tipo) from act) = 9);
select pg_temp.t('V2 el versionado NO borró nada: CADA uno de los 7 tipos que ya existían conserva sus versiones anteriores (inactivas), y cookies las tres', (select bool_and(exists (select 1 from legal_documents l where l.tipo = t and l.clinica_id is null and not l.activo and l.version like '0.%')) from unnest(array['privacy_simplified','privacy_integral','terms','cookies','security','retention','data_processing_agreement']) t) and (select count(*) from legal_documents where tipo = 'cookies' and clinica_id is null and not activo) = 3 and (select count(*) from legal_documents where clinica_id is null and not activo) >= 15);
select pg_temp.t('V3 ningún documento vigente trae advertencias editoriales, marcadores ni texto entre corchetes', not exists (select 1 from act where contenido ~* 'borrador|provisional|pendiente de (revisi[oó]n|abogado|configurar)' or contenido ~ '\[[^]]{0,60}\]|TODO LEGAL' or titulo ~* 'borrador'));
select pg_temp.t('V4 solo quedan los marcadores {{VERSION}} y {{FECHA_ACTUALIZACION}} (ninguno toma datos de la clínica)', not exists (select 1 from act, regexp_matches(contenido, '\{\{([A-Z_]+)\}\}', 'g') m where m[1] not in ('VERSION', 'FECHA_ACTUALIZACION')) and (select bool_and(contenido ~ '\{\{VERSION\}\}' and contenido ~ '\{\{FECHA_ACTUALIZACION\}\}') from act));
select pg_temp.t('V5 identidad: el titular aparece con su nombre completo donde corresponde, y no se inventan razón social, RFC, institución ni otros correos', (select bool_and(contenido like '%Eduardo Heriberto Iglesias Arines%') from act where tipo in ('privacy_simplified', 'privacy_integral', 'terms', 'data_processing_agreement', 'arco_procedure'))
  and not exists (select 1 from act where contenido ~* 'S\.A\.|raz[oó]n social|Universidad|UPEMEX|\mRFC\M' or contenido ~ '\m[A-ZÑ&]{3,4}[0-9]{6}[A-Z0-9]{3}\M')
  and not exists (select 1 from act, regexp_matches(contenido, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', 'g') m where m[1] <> 'sirso191206@gmail.com' or true and m[1] is distinct from 'sirso191206@gmail.com'));
select pg_temp.t('V6 conservación: el único plazo en años es el mínimo de 5 del expediente (NOM-004, numeral 5.4); nada se elimina automáticamente', (select (select count(*) from regexp_matches(contenido, '[0-9]+ años', 'g')) = 1 and contenido ~ '5 años contados a partir de la fecha del último acto médico' and contenido ~ 'numeral 5\.4' and contenido ~ 'Nada se elimina de forma automática' and contenido ~ 'Cancelar una suscripción no elimina el expediente clínico' from act where tipo = 'retention'));
select pg_temp.t('V7 no se afirma lo que el software no hace (integraciones de WhatsApp, IP guardada, certificaciones, aprobaciones, cumplimiento declarado)', not exists (select 1 from act where contenido ~* 'integr[a-z]* .{0,40}whatsapp|direcci[oó]n IP, navegador|certificad|aprobad[oa] por|avalad|cumple con (la ley|la nom)'));
select pg_temp.t('V8 la restricción de tipos admite arco_procedure y consents', (select count(*) from legal_documents where tipo in ('arco_procedure', 'consents') and activo) = 2 and exists (select 1 from pg_constraint where conname = 'legal_documents_tipo_check' and pg_get_constraintdef(oid) like '%arco_procedure%' and pg_get_constraintdef(oid) like '%consents%'));
do $$ begin begin insert into legal_documents (tipo, version, titulo, contenido, activo) values ('tipo_inventado', '9', 'x', 'x', false); insert into _res values ('V9 un tipo desconocido es rechazado', false); exception when check_violation then insert into _res values ('V9 un tipo desconocido es rechazado', true); end; end $$;

insert into auth.users (id, email) select ('a9000000-0000-0000-0000-0000000000'||lpad(g::text,2,'0'))::uuid, 'lg'||g||'@x.mx' from generate_series(1,4) g;
insert into clinicas (id, nombre) values ('c9000000-0000-0000-0000-00000000000a','A'),('c9000000-0000-0000-0000-00000000000b','B');
select fn_asignar_plan_interno(null, c, 'empresarial', 'mensual') from unnest(array['c9000000-0000-0000-0000-00000000000a','c9000000-0000-0000-0000-00000000000b']::uuid[]) c;
insert into usuarios (id, clinica_id, nombre, correo, rol) values ('a9000000-0000-0000-0000-000000000001','c9000000-0000-0000-0000-00000000000a','Owner A','lg1@x.mx','owner'),('a9000000-0000-0000-0000-000000000002','c9000000-0000-0000-0000-00000000000a','Dentista D','lg2@x.mx','dentista'),('a9000000-0000-0000-0000-000000000003','c9000000-0000-0000-0000-00000000000b','Owner B','lg3@x.mx','owner');
create temp table ids as select (select id from legal_documents where tipo = 'terms' and activo and clinica_id is null) as terms, (select id from legal_documents where tipo = 'terms' and version = '0.2-borrador') as terms_viejo;
insert into legal_documents (id, clinica_id, tipo, version, titulo, contenido, activo) values ('d9000000-0000-0000-0000-00000000000b', 'c9000000-0000-0000-0000-00000000000b', 'privacy_integral', 'B1', 'Aviso de la clínica B', 'texto', true);
select pg_temp.como('a9000000-0000-0000-0000-000000000002', format('with i as (insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version, aceptado_en, metodo) values (%L, %L, %L, ''VERSION-FORJADA'', ''2000-01-01'', ''forjada'') returning 1) select count(*)::text from i', 'a9000000-0000-0000-0000-000000000002', 'c9000000-0000-0000-0000-00000000000a', (select terms from ids)));
select pg_temp.t('A1 una persona registra su aceptación de un documento vigente, y el servidor FIJA la versión (la del documento, no la que mande el cliente) y la fecha real (no la que mande el cliente)',
  (select documento_version = '1.0' and aceptado_en > now() - interval '5 minutes' and aceptado_en <= now() + interval '1 minute' and metodo = 'forjada' from legal_acceptances where usuario_id = 'a9000000-0000-0000-0000-000000000002'));
select pg_temp.t('A2 no se puede aceptar una versión que ya no está vigente', pg_temp.hint(pg_temp.como('a9000000-0000-0000-0000-000000000002', format('with i as (insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version) values (%L, %L, %L, ''0.2'') returning 1) select count(*)::text from i', 'a9000000-0000-0000-0000-000000000002', 'c9000000-0000-0000-0000-00000000000a', (select terms_viejo from ids)))) = 'ACEPTACION_DOCUMENTO_NO_VIGENTE');
select pg_temp.t('A3 no se puede aceptar el documento propio de OTRA clínica, pero su propietario sí', pg_temp.hint(pg_temp.como('a9000000-0000-0000-0000-000000000002', format('with i as (insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version) values (%L, %L, %L, ''x'') returning 1) select count(*)::text from i', 'a9000000-0000-0000-0000-000000000002', 'c9000000-0000-0000-0000-00000000000a', 'd9000000-0000-0000-0000-00000000000b'))) = 'ACEPTACION_DOCUMENTO_AJENO'
  and pg_temp.como('a9000000-0000-0000-0000-000000000003', format('with i as (insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version) values (%L, %L, %L, ''x'') returning 1) select count(*)::text from i', 'a9000000-0000-0000-0000-000000000003', 'c9000000-0000-0000-0000-00000000000b', 'd9000000-0000-0000-0000-00000000000b')) = '1');
select pg_temp.t('A4 nadie puede registrar una aceptación a nombre de OTRA persona', pg_temp.como('a9000000-0000-0000-0000-000000000002', format('with i as (insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version) values (%L, %L, %L, ''x'') returning 1) select count(*)::text from i', 'a9000000-0000-0000-0000-000000000001', 'c9000000-0000-0000-0000-00000000000a', (select terms from ids))) like 'ERR|%');
select pg_temp.t('A5 la evidencia es inmutable para las personas usuarias: no pueden modificarla ni borrarla (0 filas o permiso denegado)',
  coalesce(pg_temp.como('a9000000-0000-0000-0000-000000000002', 'with u as (update legal_acceptances set documento_version = ''x'', aceptado_en = now() - interval ''10 years'' returning 1) select count(*)::text from u'), '0') in ('0') or pg_temp.como('a9000000-0000-0000-0000-000000000002', 'with u as (update legal_acceptances set documento_version = ''x'' returning 1) select count(*)::text from u') like 'ERR|%');
select pg_temp.t('A6 tampoco pueden borrarla', pg_temp.como('a9000000-0000-0000-0000-000000000002', 'with d as (delete from legal_acceptances returning 1) select count(*)::text from d') in ('0') or pg_temp.como('a9000000-0000-0000-0000-000000000002', 'with d as (delete from legal_acceptances returning 1) select count(*)::text from d') like 'ERR|%');
select pg_temp.t('A7 sigue intacta tras esos intentos (versión y fecha originales)', (select documento_version = '1.0' and aceptado_en > now() - interval '5 minutes' from legal_acceptances where usuario_id = 'a9000000-0000-0000-0000-000000000002'));
select pg_temp.t('A8 aislamiento: cada persona ve solo sus aceptaciones, el propietario las de su clínica y el de otra clínica nada ajeno', pg_temp.como('a9000000-0000-0000-0000-000000000002', 'select count(*)::text from legal_acceptances') = '1'
  and (select count(*) from legal_acceptances) = 2 and pg_temp.como('a9000000-0000-0000-0000-000000000001', 'select count(*)::text from legal_acceptances') = '1' and pg_temp.como('a9000000-0000-0000-0000-000000000003', 'select count(*)::text from legal_acceptances where clinica_id = ''c9000000-0000-0000-0000-00000000000a''') = '0');
select pg_temp.t('A9 el disparador no es invocable por usuarios (sin permisos) y existe uno solo sobre la tabla', not has_function_privilege('authenticated', 'fn_validar_aceptacion_legal()', 'execute') and not has_function_privilege('anon', 'fn_validar_aceptacion_legal()', 'execute') and (select count(*) from pg_trigger where tgrelid = 'public.legal_acceptances'::regclass and tgname = 'trg_validar_aceptacion_legal' and not tgisinternal) = 1);
insert into legal_acceptances (usuario_id, clinica_id, documento_id, documento_version, aceptado_en, metodo) values ('a9000000-0000-0000-0000-000000000001', 'c9000000-0000-0000-0000-00000000000a', (select terms_viejo from ids), '0.2-borrador', '2026-01-02 03:04:05+00', 'restaurada');
select pg_temp.t('A10 una inserción de SERVIDOR (service_role, migración o restauración de respaldo) conserva la evidencia TAL CUAL: misma versión, misma fecha y documentos ya no vigentes (si no, restaurar un respaldo la corrompería)', (select documento_version = '0.2-borrador' and aceptado_en = '2026-01-02 03:04:05+00' and metodo = 'restaurada' from legal_acceptances where metodo = 'restaurada'));
do $$ declare v_f int; v_o int; begin
  select count(*) filter (where ok), count(*) filter (where not ok) into v_o, v_f from _res;
  raise notice 'RESULTADO 106: % pasaron, % fallaron (de %)', v_o, v_f, v_o + v_f;
  if v_f > 0 then raise exception 'FALLARON: %', (select string_agg(left(nombre, 90), ' | ') from _res where not ok); end if;
end $$;
rollback;
